package fr.roadguard.app;
import android.app.Application;import org.json.JSONObject;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={27,28},application=Application.class)
public class MapPaletteRuntimeTest {
 @Test public void allPresetsAndCustomColorsAreBounded()throws Exception{java.util.Set<String> distinct=new java.util.HashSet<>();for(boolean night:new boolean[]{false,true})for(String id:MapAppearance.IDS){JSONObject p=MapAppearance.palette(id,night,"{}");for(String key:MapAppearance.KEYS)assertTrue(p.getString(key).matches("#[a-f0-9]{6}"));if(!"custom".equals(id))distinct.add(p.toString());}assertEquals(12,distinct.size());JSONObject p=MapAppearance.palette("custom",false,"{\"road\":\"#ABCDEF\",\"water\":\"url(evil)\",\"rasterHue\":999}");assertEquals("#abcdef",p.getString("road"));assertEquals("#88c7e7",p.getString("water"));assertEquals(360,p.getInt("rasterHue"));}
 @Test public void dayAndNightCustomPalettesPersistIndependently()throws Exception{Application a=RuntimeEnvironment.getApplication();MapAppearance.preferences(a).edit().putString("map_appearance_pack","custom").putString("map_palette_custom_day","{\"road\":\"#123456\"}").putString("map_palette_custom_night","{\"road\":\"#fedcba\"}").commit();assertEquals("#123456",MapAppearance.current(a,false).getString("road"));assertEquals("#fedcba",MapAppearance.current(a,true).getString("road"));}
 @Test public void javaPalettesMatchTheSharedJavaScriptRenderer()throws Exception{java.io.InputStream in=getClass().getResourceAsStream("/map-palettes-reference.json");assertNotNull(in);java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);in.close();org.json.JSONArray cases=new org.json.JSONArray(out.toString("UTF-8"));for(int i=0;i<cases.length();i++){JSONObject c=cases.getJSONObject(i),actual=MapAppearance.palette(c.getString("id"),c.getBoolean("night"),c.getJSONObject("custom").toString()),expected=c.getJSONObject("expected");java.util.Iterator<String> keys=expected.keys();while(keys.hasNext()){String key=keys.next();Object a=actual.get(key),e=expected.get(key);if(a instanceof Number&&e instanceof Number)assertEquals(((Number)e).doubleValue(),((Number)a).doubleValue(),.000001);else assertEquals(e,a);}}}
}
